39	static constexpr uint8_t sourceHarmonic = 5;
40	static constexpr uint8_t LOHarmonic = 3;
41	
42	static constexpr float alternativeSamplerate = 914285.7143f;
43	static constexpr uint8_t alternativePrescaler = 102400000UL / alternativeSamplerate;
44	static_assert(alternativePrescaler * alternativeSamplerate == 102400000UL, "alternative ADCSamplerate can not be reached exactly");
45	static constexpr uint16_t alternativePhaseInc = 4096 * HW::DefaultIF2 / alternativeSamplerate;
46	static_assert(alternativePhaseInc * alternativeSamplerate == 4096 * HW::DefaultIF2, "DFT can not be computed for 2.IF when using alternative samplerate");
