48	// Constants for USB buffer overflow prevention
49	static constexpr uint16_t maxPointsBetweenHalts = 40;
50	static constexpr uint16_t full2portDatapointSize = 66;// See Protocol::VNADatapoint::
51	static constexpr uint32_t reservedUSBbuffer = (maxPointsBetweenHalts + 2 /*additional buffer*/) * (full2portDatapointSize + 8 /*USB packet overhead*/);
