53	static uint32_t PLLRefFreqs[] = {HW::PLLRef, HW::PLLRef - 1000000};
54	static constexpr uint8_t PLLRefFreqsNum = sizeof(PLLRefFreqs)/sizeof(PLLRefFreqs[0]);
55	static uint8_t sourceRefIndex, LO1RefIndex;
