59	static uint64_t getPointFrequency(uint16_t pointNum) {
60		if(!settings.logSweep) {
61			return settings.f_start + (settings.f_stop - settings.f_start) * pointNum / (settings.points - 1);
62		} else {
63			static uint16_t lastPointNum = 0;
64			if (pointNum == 0) {
65				logFrequency = settings.f_start;
66			} else if(pointNum == lastPointNum) {
67				// nothing to do
68			} else if(pointNum == lastPointNum + 1) {
69				logFrequency *= logMultiplier;
70			} else {
71				logFrequency = settings.f_start * pow(10.0, pointNum * log10((double)settings.f_stop / settings.f_start) / (settings.points - 1));
72			}
73			lastPointNum = pointNum;
74			return logFrequency;
75		}
76	}
77	
78	static bool setPLLFrequencies(uint64_t f) {
79		uint64_t sourceFreq = 0;
80		uint64_t LOFreq = 0;
81		if(f > HW::Info.limits_maxFreq) {
82			sourceFreq = f / sourceHarmonic;
83			LOFreq = (f + HW::getIF1()) / LOHarmonic;
84		} else {
85			if(f >= HW::BandSwitchFrequency) {
86				sourceFreq = f;
87			}
88			LOFreq = f + HW::getIF1();
89		}
90		if(sourceFreq >= HW::BandSwitchFrequency) {
91			Source.SetFrequency(sourceFreq);
92		}
93		LO1.SetFrequency(LOFreq);
94		bool needsRefSwitch = false;
95		if(settings.suppressPeaks) {
96			// Integer spurs can cause a small peak.
97			if(sourceFreq >= HW::BandSwitchFrequency) {
98				uint32_t sourceDist = Source.DistanceToIntegerSpur();
99				if((sourceDist > 0) && (sourceDist < 3 * HW::getIF2())) {
100					LOG_DEBUG("Source spur at %lu: %lu", (uint32_t) f, sourceDist);
101					sourceRefIndex = !sourceRefIndex;
102					Source.SetReference(PLLRefFreqs[sourceRefIndex], false, 1, false);
103					Source.SetFrequency(sourceFreq);
104					needsRefSwitch = true;
105				}
106			}
107			uint32_t LODist = LO1.DistanceToIntegerSpur();
108			if((LODist > 0) && (LODist  < 3 * HW::getIF2())) {
109				LOG_DEBUG("LO spur at %lu", (uint32_t) f);
110				LO1RefIndex = !LO1RefIndex;
111				LO1.SetReference(PLLRefFreqs[LO1RefIndex], false, 1, false);
112				LO1.SetFrequency(LOFreq);
113				needsRefSwitch = true;
114			}
115		}
116		return needsRefSwitch;
117	}
118	
119	static bool needs2LOshift(uint64_t f, uint32_t current2LO, uint32_t IFBW, uint32_t *new2LO) {
120		// Check if 2.LO needs to be shifted
121		uint64_t actualSource, actual1LO;
122		actualSource = Source.GetActualFrequency();
123		actual1LO = LO1.GetActualFrequency();
124		if(f > HW::Info.limits_maxFreq) {
125			actualSource *= sourceHarmonic;
126			actual1LO *= LOHarmonic;
127		} else if(f < HW::BandSwitchFrequency) {
128			// can use the lowband PLL with high frequency resolution, assume perfect frequency match
129			actualSource = f;
130		}
131		uint32_t actualFirstIF = actual1LO - actualSource;
132		uint32_t actualFinalIF = actualFirstIF - current2LO;
133		uint32_t IFdeviation = abs(actualFinalIF - HW::getIF2());
134		if(IFdeviation > IFBW / 2) {
135			*new2LO = actualFirstIF - HW::getIF2();
136			return true;
137		} else {
138			// no shift required
139			return false;
140		}
141	}
