143	bool VNA::Setup(Protocol::SweepSettings s) {
144		// Abort possible active sweep first
145		VNA::Stop();
146		vTaskDelay(5);
147		data.clear();
148		HW::SetMode(HW::Mode::VNA);
149		Trigger::SetInput(false);
150	
151		sourceRefIndex = 0;
152		LO1RefIndex = 0;
153		Source.SetReference(PLLRefFreqs[sourceRefIndex], false, 1, false);
154		LO1.SetReference(PLLRefFreqs[LO1RefIndex], false, 1, false);
155	
156		FPGA::SetMode(FPGA::Mode::FPGA);
157		FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, HW::getADCPrescaler());
158		FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, HW::getDFTPhaseInc());
159		if(settings.points > FPGA::MaxPoints) {
160			settings.points = FPGA::MaxPoints;
161		}
162		if(settings.dwell_time > HW::Info.limits_maxDwellTime) {
163			settings.dwell_time = HW::Info.limits_maxDwellTime;
164		}
165		settings = s;
166		// calculate factor between adjacent points for log sweep for faster calculation when sweeping
167		logMultiplier = pow((double) settings.f_stop / settings.f_start, 1.0 / (settings.points-1));
168		// Configure sweep
169		FPGA::SetNumberOfPoints(settings.points);
170		uint32_t samplesPerPoint = (HW::getADCRate() / s.if_bandwidth);
171		// round up to next multiple of 16 (16 samples are spread across 5 IF2 periods)
172		if(samplesPerPoint%16) {
173			samplesPerPoint += 16 - samplesPerPoint%16;
174		}
175		actualBandwidth = HW::getADCRate() / samplesPerPoint;
176		// has to be one less than actual number of samples
177		FPGA::SetSamplesPerPoint(samplesPerPoint);
178	
179		FPGA::SetSettlingTime(s.dwell_time + HW::getPLLSettlingDelay());
180	
181		// reset unlevel flag if it was set from a previous sweep/mode
182		HW::SetOutputUnlevel(false);
183		// Start with average level
184		auto cdbm = (s.cdbm_excitation_start + s.cdbm_excitation_stop) / 2;
185		// correct for port 1, assumes port 2 is identical
186		auto centerFreq = (s.f_start + s.f_stop) / 2;
187		// force calculation of amplitude setting for PLL, even with lower frequencies
188		if(centerFreq < HW::BandSwitchFrequency) {
189			centerFreq = HW::BandSwitchFrequency;
190		}
191		auto amplitude = HW::GetAmplitudeSettings(cdbm, centerFreq, true, false);
192		if(amplitude.unlevel) {
193			HW::SetOutputUnlevel(true);
194		}
195	
196		uint8_t fixedAttenuatorHighband = amplitude.attenuator;
197		Source.SetPowerOutA(amplitude.highBandPower, true);
198	
199		// amplitude calculation for lowband
200		amplitude = HW::GetAmplitudeSettings(cdbm, HW::BandSwitchFrequency / 2, true, false);
201		if(amplitude.unlevel) {
202			HW::SetOutputUnlevel(true);
203		}
204		uint8_t fixedAttenuatorLowband = amplitude.attenuator;
205		fixedPowerLowband = amplitude.lowBandPower;
206	
207		FPGA::WriteMAX2871Default(Source.GetRegisters());
208	
209		last_LO2 = HW::getIF1() - HW::getIF2();
210		Si5351.Enable(SiChannel::Port1LO2);
211		Si5351.Enable(SiChannel::Port2LO2);
212		Si5351.Enable(SiChannel::RefLO2);
213		Si5351.SetPLL(Si5351C::PLL::B, last_LO2*HW::LO2Multiplier, HW::Ref::getSource(), false);
214		Si5351.ResetPLL(Si5351C::PLL::B);
215		Si5351.WaitForLock(Si5351C::PLL::B, 10);
216	
217		zerospan = (s.f_start == s.f_stop) && (s.cdbm_excitation_start == s.cdbm_excitation_stop);
218	
219		bool last_lowband = false;
220	
221		uint16_t pointsWithoutHalt = 0;
222	
223		// Transfer PLL configuration to FPGA
224		for (uint16_t i = 0; i < settings.points; i++) {
225			uint64_t freq = getPointFrequency(i);
226			int16_t power = s.cdbm_excitation_start + (s.cdbm_excitation_stop - s.cdbm_excitation_start) * i / (settings.points - 1);
227			freq = Cal::FrequencyCorrectionToDevice(freq);
228	
229			bool needs_halt = false;
230			bool lowband = false;
231			if (freq < HW::BandSwitchFrequency) {
232				needs_halt = true;
233				lowband = true;
234			}
235			if(i == 0) {
236				// halt before first point (makes sure that the 2.LO gets configured correctly if it was shifted for the last point in
237				// the previous sweep
238				needs_halt = true;
239			}
240			// SetFrequency only manipulates the register content in RAM, no SPI communication is done.
241			// No mode-switch of FPGA necessary here.
242			if(setPLLFrequencies(freq)) {
243				needs_halt = true;
244			}
245			uint32_t new_LO2;
246			auto needs_shift = needs2LOshift(freq, last_LO2, actualBandwidth, &new_LO2);
247			if(needs_shift) {
248				if(s.suppressPeaks) {
249					needs_halt = true;
250					last_LO2 = new_LO2;
251				} else {
252					LOG_WARN("Point at f=%lu%06lu needs an LO shift but the feature is disabled. This will cause a peak.", (uint32_t) (freq/1000000), (uint32_t) (freq%1000000));
253				}
254			}
255			if (last_lowband && !lowband) {
256				// additional halt before first highband point to enable highband source
257				needs_halt = true;
258			}
259	
260			// halt on regular intervals to prevent USB buffer overflow
261			if(!needs_halt) {
262				pointsWithoutHalt++;
263				if(pointsWithoutHalt > maxPointsBetweenHalts) {
264					needs_halt = true;
265					pointsWithoutHalt = 0;
266				}
267			} else {
268				pointsWithoutHalt = 0;
269			}
270	
271			uint8_t attenuator = freq >= HW::BandSwitchFrequency ? fixedAttenuatorHighband : fixedAttenuatorLowband;
272			if(!s.fixedPowerSetting) {
273				// adapt power level throughout the sweep
274				amplitude = HW::GetAmplitudeSettings(power, freq, true, false);
275				if(freq >= HW::BandSwitchFrequency) {
276					Source.SetPowerOutA(amplitude.highBandPower, true);
277				}
278				if(amplitude.unlevel) {
279					HW::SetOutputUnlevel(true);
280				}
281				attenuator = amplitude.attenuator;
282			}
283	
284			// needs halt before first point to allow PLLs to settle
285			if (i == 0) {
286				needs_halt = true;
287			}
288	
289			FPGA::WriteSweepConfig(i, lowband, Source.GetRegisters(),
290					LO1.GetRegisters(), attenuator, freq,
291					FPGA::Samples::SPPRegister, needs_halt);
292			last_lowband = lowband;
293		}
294		// reset a possibly changed PLL reference index
295		sourceRefIndex = 0;
296		LO1RefIndex = 0;
297		Source.SetReference(PLLRefFreqs[sourceRefIndex], false, 1, false);
298		LO1.SetReference(PLLRefFreqs[LO1RefIndex], false, 1, false);
299		// revert clk configuration to previous value (might have been changed in sweep calculation)
300		Si5351.SetCLK(SiChannel::RefLO2, HW::getIF1() - HW::getIF2(), Si5351C::PLL::B, Si5351C::DriveStrength::mA2);
301		Si5351.ResetPLL(Si5351C::PLL::B);
302		Si5351.WaitForLock(Si5351C::PLL::B, 10);
303		// Enable mixers/amplifier/PLLs
304		FPGA::SetWindow(FPGA::Window::Kaiser);
305		FPGA::Enable(FPGA::Periphery::Port1Mixer);
306		FPGA::Enable(FPGA::Periphery::Port2Mixer);
307		FPGA::Enable(FPGA::Periphery::RefMixer);
308		FPGA::Enable(FPGA::Periphery::Amplifier);
309		FPGA::Enable(FPGA::Periphery::SourceChip);
310		FPGA::Enable(FPGA::Periphery::SourceRF);
311		FPGA::Enable(FPGA::Periphery::LO1Chip);
312		FPGA::Enable(FPGA::Periphery::LO1RF);
313		FPGA::SetupSweep(s.stages, s.port1Stage, s.port2Stage, s.syncMode != 0, s.syncMaster);
314		Trigger::SetMode((Trigger::Mode) s.syncMode);
315		FPGA::Enable(FPGA::Periphery::PortSwitch);
316		pointCnt = 0;
317		stageCnt = 0;
318		adcShifted = false;
319		active = true;
320		// Enable new data and sweep halt interrupt
321		FPGA::EnableInterrupt(FPGA::Interrupt::NewData);
322		FPGA::EnableInterrupt(FPGA::Interrupt::SweepHalted);
323		// Start the sweep if not configured for standby
324		firstPoint = true;
325		if (settings.standby) {
326			waitingInStandby = true;
327		}
328		else {
329			FPGA::StartSweep();
330		}
331		return true;
332	}
