355	static void PassOnData() {
356		Protocol::PacketInfo info;
357		info.type = Protocol::PacketType::VNADatapoint;
358		info.VNAdatapoint = &data;
359		if(!Communication::Send(info)) {
360			LOG_ERR("Failed to transmit VNADatapoint");
361		}
362		data.clear();
363	}
364	
365	bool VNA::MeasurementDone(const FPGA::SamplingResult &result) {
366		if(!active) {
367			return false;
368		}
369		if(result.pointNum != pointCnt || result.stageNum != stageCnt) {
370			LOG_WARN("Indicated point does not match (%u != %u, %d != %d)", result.pointNum, pointCnt, result.stageNum, stageCnt);
371			FPGA::AbortSweep();
372			return false;
373		}
374		// normal sweep mode
375		data.addValue(result.P1I, result.P1Q, stageCnt, (int) Protocol::Source::Port1);
376		data.addValue(result.P2I, result.P2Q, stageCnt, (int) Protocol::Source::Port2);
377		data.addValue(result.RefI, result.RefQ, stageCnt, (int) Protocol::Source::Port1 | (int) Protocol::Source::Port2 | (int) Protocol::Source::Reference);
378		data.pointNum = pointCnt;
379		if(zerospan) {
380			uint64_t timestamp = HW::getLastISRTimestamp();
381			if(firstPoint) {
382				data.us = 0;
383				firstPointTime = timestamp;
384				firstPoint = false;
385			} else {
386				data.us = timestamp - firstPointTime;
387			}
388		} else {
389			// non-zero span, set frequency/power
390			data.frequency = getPointFrequency(pointCnt);
391			data.cdBm = settings.cdbm_excitation_start + (settings.cdbm_excitation_stop - settings.cdbm_excitation_start) * pointCnt / (settings.points - 1);
392		}
393		// figure out whether this sweep point is complete
394		stageCnt++;
395		if(stageCnt > settings.stages) {
396			// point is complete
397			stageCnt = 0;
398			STM::DispatchToInterrupt(PassOnData);
399			pointCnt++;
400			if (pointCnt >= settings.points) {
401				// reached end of sweep, start again
402				pointCnt = 0;
403				// request to trigger work function
404				return true;
405			}
406		}
407		return false;
408	}
409	
410	void VNA::Work() {
411		// end of sweep
412		if(Trigger::GetMode() != Trigger::Mode::ExtRef) {
413			HW::Ref::update();
414		}
415		// Stop the sweep. The source may not have been active for the last phase but the PLL
416		// must be enabled for reading the temperature. Stopping the sweep implicitly enables
417		// the source PLL
418		FPGA::StopSweep();
419		// Compile info packet
420		Protocol::PacketInfo packet;
421		packet.type = Protocol::PacketType::DeviceStatus;
422		if(HW::getStatusUpdateFlag()) {
423			HW::getDeviceStatus(&packet.status, true);
424			Communication::Send(packet);
425		}
426		// do not reset unlevel flag here, as it is calculated only once at the setup of the sweep
427		// Start next sweep if not configured for standby
428		if (settings.standby) {
429			waitingInStandby = true;
430		}
431		else {
432			FPGA::StartSweep();
433		}
434	
435	}
436	
437	void VNA::SweepHalted() {
438		if(!active) {
439			return;
440		}
441		// Resuming the halted sweep requires I2C bus operations to the Si5355. When trigger synchronization is enabled
442		// in the external reference mode, this might collide with the trigger input check. Instead both these actions
443		// are handled through the STM::DispatchToInterrupt functionality, ensuring that they do not interrupt each other
444		STM::DispatchToInterrupt([](){
445			LOG_DEBUG("Halted before point %d", pointCnt);
446			bool adcShiftRequired = false;
447			uint64_t frequency = getPointFrequency(pointCnt);
448			frequency = Cal::FrequencyCorrectionToDevice(frequency);
449			int16_t power = settings.cdbm_excitation_start
450					+ (settings.cdbm_excitation_stop - settings.cdbm_excitation_start)
451							* pointCnt / (settings.points - 1);
452			if (frequency < HW::BandSwitchFrequency) {
453				auto driveStrength = fixedPowerLowband;
454				if(!settings.fixedPowerSetting) {
455					auto amplitude = HW::GetAmplitudeSettings(power, frequency, true, false);
456					// attenuator value has already been set in sweep setup
457					driveStrength = amplitude.lowBandPower;
458				}
459	
460				// need the Si5351 as Source
461				bool freqSuccess = Si5351.SetCLK(SiChannel::LowbandSource, frequency, Si5351C::PLL::A, driveStrength, false);
462				static bool lowbandDisabled = false;
463				if (pointCnt == 0) {
464					// First point in sweep, switch to correct source
465					FPGA::Disable(FPGA::Periphery::SourceRF);
466					lowbandDisabled = true;
467				}
468				if(lowbandDisabled && freqSuccess) {
469					// frequency is valid, can enable lowband source now
470					Si5351.Enable(SiChannel::LowbandSource);
471					Delay::ms(10);
472					lowbandDisabled = false;
473				}
474	
475				// At low frequencies the 1.LO feedthrough mixes with the 2.LO in the second mixer.
476				// Depending on the stimulus frequency, the resulting mixing product might alias to the 2.IF
477				// in the ADC which causes a spike. Check for this and shift the ADC sampling frequency if necessary
478	
479				uint32_t LO_mixing = (HW::getIF1() + frequency) - (HW::getIF1() - HW::getIF2());
480				if(abs(Util::Alias(LO_mixing, HW::getADCRate()) - HW::getIF2()) <= actualBandwidth * 2) {
481					// the image is in or near the IF bandwidth and would cause a peak
482					// Use a slightly different ADC sample rate if possible
483					if(HW::getIF2() == HW::DefaultIF2) {
484						adcShiftRequired = true;
485					}
486				}
487			} else if(!FPGA::IsEnabled(FPGA::Periphery::SourceRF)){
488				// first sweep point in highband is also halted, disable lowband source
489				Si5351.Disable(SiChannel::LowbandSource);
490				FPGA::Enable(FPGA::Periphery::SourceRF);
491			}
492	
493			if (pointCnt == 0 && settings.suppressPeaks) {
494				sourceRefIndex = 0;
495				LO1RefIndex = 0;
496				Source.SetReference(PLLRefFreqs[sourceRefIndex], false, 1, false);
497				LO1.SetReference(PLLRefFreqs[LO1RefIndex], false, 1, false);
498				// update PLL reference frequencies
499				Si5351.SetCLK(SiChannel::Source, PLLRefFreqs[sourceRefIndex], Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
500				Si5351.SetCLK(SiChannel::LO1, PLLRefFreqs[LO1RefIndex], Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
501				last_LO2 = HW::getIF1() - HW::getIF2();
502				Si5351.SetPLL(Si5351C::PLL::B, last_LO2*HW::LO2Multiplier, HW::Ref::getSource(), false);
503				Si5351.ResetPLL(Si5351C::PLL::B);
504				Si5351.WaitForLock(Si5351C::PLL::B, 10);
505				HAL_Delay(2);
506			}
507	
508			if(settings.suppressPeaks) {
509				// does not actually change PLL settings, just calculates the register values and
510				// is required to determine the need for a 2.LO shift
511				if(setPLLFrequencies(frequency)) {
512					// update PLL reference frequencies
513					Si5351.SetCLK(SiChannel::Source, PLLRefFreqs[sourceRefIndex], Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
514					Si5351.SetCLK(SiChannel::LO1, PLLRefFreqs[LO1RefIndex], Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
515				}
516				if(needs2LOshift(frequency, last_LO2, actualBandwidth, &last_LO2)) {
517					Si5351.SetPLL(Si5351C::PLL::B, last_LO2*HW::LO2Multiplier, HW::Ref::getSource(), false);
518					Si5351.ResetPLL(Si5351C::PLL::B);
519					Si5351.WaitForLock(Si5351C::PLL::B, 10);
520					// PLL reset causes the 2.LO to turn off briefly and then ramp on back, needs delay before next point
521					Delay::us(1500);
522				}
523			}
524	
525			if(adcShiftRequired) {
526				FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, alternativePrescaler);
527				FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, alternativePhaseInc);
528				adcShifted = true;
529			} else if(adcShifted) {
530				// reset to default value
531				FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, HW::getADCPrescaler());
532				FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, HW::getDFTPhaseInc());
533				adcShifted = false;
534			}
535	
536			if(usb_available_buffer() >= reservedUSBbuffer) {
537				// enough space available, can resume immediately
538				FPGA::ResumeHaltedSweep();
539			} else {
540				// USB buffer could potentially overflow before next halted point, wait until more space is available.
541				uint32_t start = HAL_GetTick();
542				while(usb_available_buffer() < reservedUSBbuffer) {
543					if(HAL_GetTick() - start > 1000) {
544						// still no buffer space after some time, something more serious must have gone wrong
545						// -> abort sweep and return to idle
546						usb_clear_buffer();
547						FPGA::AbortSweep();
548						HW::SetIdle();
549						return;
550					}
551				}
552				FPGA::ResumeHaltedSweep();
553			}
554		});
555	}
556	
557	void VNA::Stop() {
558		active = false;
559		FPGA::AbortSweep();
560	}
561	
562	void VNA::PrintStatus() {
563		HAL_Delay(10);
564		LOG_INFO("VNA status:");
565		HAL_Delay(10);
566		LOG_INFO("Active: %d", active);
567		HAL_Delay(10);
568		LOG_INFO("Points: %d/%d", pointCnt, settings.points);
569		HAL_Delay(10);
570		LOG_INFO("Stages: %d/%d", stageCnt, settings.stages);
571		HAL_Delay(10);
572		LOG_INFO("FPGA status: 0x%04x", FPGA::GetStatus());
573	}
