19	static Protocol::SpectrumAnalyzerSettings s;
20	static uint32_t pointCnt;
21	static uint32_t points;
22	static uint32_t binSize;
23	static uint8_t signalIDstep;
24	static uint32_t sampleNum;
25	static Protocol::PacketInfo p;
26	static bool active = false;
27	static uint32_t lastLO2;
28	static uint32_t actualRBW;
29	static uint16_t DFTpoints;
30	static bool negativeDFT; // if true, a positive frequency shift at input results in a negative shift at the 2.IF. Handle DFT accordingly
31	
32	static float port1Measurement[FPGA::DFTbins], port2Measurement[FPGA::DFTbins];
33	
34	static uint8_t signalIDsteps;
35	static std::array<uint8_t, 4> signalIDprescalers;
36	static uint8_t attenuator;
37	static int64_t trackingFreq;
38	static bool trackingLowband;
39	
40	static bool firstSample;
41	
42	// Zero span variables
43	static uint64_t firstPointTime;
44	static bool firstPoint; // indicates the first point to be transmitted to the GUI, sets the firstPointTime
45	static bool zerospan;
46	
47	static uint32_t PLLRefFreqs[] = {HW::PLLRef, HW::PLLRef - 1000000};
48	static constexpr uint8_t PLLRefFreqsNum = sizeof(PLLRefFreqs)/sizeof(PLLRefFreqs[0]);
49	static uint8_t PLLRefIndex;
50	
51	static void setPLLReference() {
52		Si5351.SetCLK(SiChannel::Source, PLLRefFreqs[PLLRefIndex], Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
53		Si5351.SetCLK(SiChannel::LO1, PLLRefFreqs[PLLRefIndex], Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
54		Source.SetReference(PLLRefFreqs[PLLRefIndex], false, 1, false);
55		LO1.SetReference(PLLRefFreqs[PLLRefIndex], false, 1, false);
56	}
57	
58	static void StartNextSample() {
59		uint64_t freq = s.f_start + (s.f_stop - s.f_start) * pointCnt / (points - 1);
60		freq = Cal::FrequencyCorrectionToDevice(freq);
61		uint64_t LO1freq;
62		uint32_t LO2freq;
63		bool LO1inverted = false;
64		switch(signalIDstep) {
65		case 0:
66			// reset minimum amplitudes in first signal ID step
67			for (uint16_t i = 0; i < DFTpoints; i++) {
68				port1Measurement[i] = std::numeric_limits<float>::max();
69				port2Measurement[i] = std::numeric_limits<float>::max();
70			}
71			// Use default LO frequencies
72			LO1freq = freq + HW::getIF1();
73			LO2freq = HW::getIF1() - HW::getIF2();
74			FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, 112);
75			FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, 1120);
76			negativeDFT = true;
77	
78			// set tracking generator to default values
79			trackingLowband = false;
80			attenuator = 0;
81			// this is the first step in each point, update tracking generator if enabled
82			if (s.trackingGenerator) {
83				auto oldTrackingFreq = trackingFreq;
84				trackingFreq = freq + s.trackingGeneratorOffset;
85				if(trackingFreq != oldTrackingFreq) {
86					// need to change the source frequency
87					oldTrackingFreq = trackingFreq;
88					if(trackingFreq > 0 && trackingFreq <= (int64_t) HW::Info.limits_maxFreq) {
89						// tracking frequency is valid, calculate required settings and select band
90						auto amplitude = HW::GetAmplitudeSettings(s.trackingPower, trackingFreq, s.applySourceCorrection, s.trackingGeneratorPort);
91						// only set the flag here, it is reset at the beginning of each sweep (this makes sure it is set if any of the points are not reached by the TG)
92						if(amplitude.unlevel) {
93							HW::SetOutputUnlevel(true);
94						}
95						attenuator = amplitude.attenuator;
96						if(trackingFreq < HW::BandSwitchFrequency) {
97							Si5351.SetCLK(SiChannel::LowbandSource, trackingFreq, Si5351C::PLL::A, amplitude.lowBandPower, false);
98							FPGA::Disable(FPGA::Periphery::SourceChip);
99							FPGA::Disable(FPGA::Periphery::SourceRF);
100							trackingLowband = true;
101						} else {
102							// Source PLL can not hit all frequencies with high enough accuracy with a single reference frequency.
103							// Check available reference frequencies for best match
104							uint8_t bestIndex = 0;
105							uint32_t smallestDeviation = UINT32_MAX;
106							for(uint8_t i=0;i<PLLRefFreqsNum;i++) {
107								Source.SetReference(PLLRefFreqs[i], false, 1, false);
108								Source.SetFrequency(trackingFreq);
109								auto actualSource = Source.GetActualFrequency();
110								uint32_t deviation = (uint32_t) abs(actualSource - trackingFreq);
111								if(deviation < smallestDeviation) {
112									smallestDeviation = deviation;
113									bestIndex = i;
114									if(deviation < actualRBW / 20) {
115										// good enough, no need to check any further
116										break;
117									}
118								}
119							}
120							if(bestIndex != PLLRefIndex) {
121								LOG_INFO("Switching ref index (current %d, requested f=%lu%06lu)", PLLRefIndex
122										,(uint32_t) (trackingFreq / 1000000), (uint32_t)(trackingFreq%1000000));
123								PLLRefIndex = bestIndex;
124								setPLLReference();
125							}
126							Source.SetFrequency(trackingFreq);
127							Source.SetPowerOutA(amplitude.highBandPower, true);
128							FPGA::Enable(FPGA::Periphery::SourceChip);
129							FPGA::Enable(FPGA::Periphery::SourceRF);
130							trackingLowband = false;
131							// selected power potentially changed, update default registers
132							FPGA::WriteMAX2871Default(Source.GetRegisters());
133						}
134					}
135				}
136			}
137			break;
138		case 1:
139			LO2freq = HW::getIF1() - HW::getIF2();
140			negativeDFT = false;
141			// Shift first LO to other side
142			// depending on the measurement frequency this is not possible or additive mixing has to be used
143			if(freq >= HW::getIF1() + HW::LO1_minFreq) {
144				// frequency is high enough to shift 1.LO below measurement frequency
145				LO1freq = freq - HW::getIF1();
146				LO1inverted = true;
147				break;
148			} else if(freq <= HW::getIF1() - HW::LO1_minFreq) {
149				// frequency is low enough to add 1.LO to measurement frequency
150				LO1freq = HW::getIF1() - freq;
151				break;
152			}
153			// unable to reach required frequency with 1.LO, skip this signal ID step
154			signalIDstep++;
155			/* no break */
156		case 2:
157			// Shift second LOs to other side
158			LO1freq = freq + HW::getIF1();
159			LO1inverted = false;
160			LO2freq = HW::getIF1() + HW::getIF2();
161			negativeDFT = false;
162			break;
163		case 3:
164			// Shift both LO to other side
165			LO2freq = HW::getIF1() + HW::getIF2();
166			negativeDFT = true;
167			// depending on the measurement frequency this is not possible or additive mixing has to be used
168			if(freq >= HW::getIF1() + HW::LO1_minFreq) {
169				// frequency is high enough to shift 1.LO below measurement frequency
170				LO1freq = freq - HW::getIF1();
171				LO1inverted = true;
172				break;
173			} else if(freq <= HW::getIF1() - HW::LO1_minFreq) {
174				// frequency is low enough to add 1.LO to measurement frequency
175				LO1freq = HW::getIF1() - freq;
176				break;
177			}
178			// unable to reach required frequency with 1.LO, skip this signal ID step
179			signalIDstep++;
180			/* no break */
181		default:
182			// Use default frequencies with different ADC samplerate to remove images in final IF
183			negativeDFT = true;
184			LO1freq = freq + HW::getIF1();
185			LO1inverted = false;
186			LO2freq = HW::getIF1() - HW::getIF2();
187			FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, signalIDprescalers[signalIDstep-4]);
188			FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, (uint16_t) signalIDprescalers[signalIDstep-4] * 10);
189		}
190		LO1.SetFrequency(LO1freq);
191		// LO1 is not able to reach all frequencies with the required precision, adjust LO2 to account for deviation
192		int32_t LO1deviation = (int64_t) LO1.GetActualFrequency() - LO1freq;
193		if(LO1inverted) {
194			LO1deviation = -LO1deviation;
195		}
196		LO2freq += LO1deviation;
197	
198		// only adjust LO2 PLL if necessary (if the deviation is significantly less than the RBW it does not matter)
199		if((uint32_t) abs(LO2freq - lastLO2) > actualRBW / 100) {
200	//		Si5351.SetPLL(Si5351C::PLL::B, LO2freq*HW::LO2Multiplier, HW::Ref::getSource());
201			Si5351.SetCLK(SiChannel::Port1LO2, LO2freq, Si5351C::PLL::B, Si5351C::DriveStrength::mA2, false);
202			Si5351.SetCLK(SiChannel::Port2LO2, LO2freq, Si5351C::PLL::B, Si5351C::DriveStrength::mA2, false);
203			lastLO2 = LO2freq;
204		}
205		if (s.UseDFT) {
206			uint32_t spacing = (s.f_stop - s.f_start) / (points - 1);
207			uint32_t start = HW::getIF2();
208			if(negativeDFT) {
209				// needs to look below the start frequency, shift start
210				start -= spacing * (DFTpoints - 1);
211			}
212			FPGA::SetupDFT(start, spacing);
213			FPGA::StartDFT();
214		}
215	
216		// Configure the sampling in the FPGA
217		FPGA::WriteSweepConfig(0, trackingLowband, Source.GetRegisters(), LO1.GetRegisters(), attenuator,
218				trackingFreq, FPGA::Samples::SPPRegister, 0,
219				FPGA::LowpassFilter::Auto);
220	
221		if(firstSample && (signalIDstep == 0)) {
222			firstSample = false;
223			// configure source/LO to allow for early settling
224			FPGA::SetMode(FPGA::Mode::SourcePLL);
225			Source.Update();
226			FPGA::SetMode(FPGA::Mode::LOPLL);
227			LO1.Update();
228			FPGA::SetMode(FPGA::Mode::FPGA);
229			HAL_Delay(20);
230		}
231	
232		FPGA::StartSweep();
233	}
234	
235	void SA::Setup(Protocol::SpectrumAnalyzerSettings settings) {
236		LOG_DEBUG("Setting up...");
237		HW::SetOutputUnlevel(false);
238		SA::Stop();
239		vTaskDelay(5);
240		s = settings;
241		HW::SetMode(HW::Mode::SA);
242		FPGA::SetMode(FPGA::Mode::FPGA);
243		FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, HW::getADCPrescaler());
244		FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, HW::getDFTPhaseInc());
245		// in almost all cases a full sweep requires more points than the FPGA can handle at a time
246		// individually start each point and do the sweep in the uC
247		FPGA::SetNumberOfPoints(1);
248		// calculate required samples per measurement for requested RBW
249		// see https://www.tek.com/blog/window-functions-spectrum-analyzers for window factors
250		constexpr float window_factors[4] = {0.89f, 2.23f, 1.44f, 3.77f};
251		sampleNum = HW::getADCRate() * window_factors[s.WindowType] / s.RBW;
252		// round up to next multiple of 16
253		if(sampleNum%16) {
254			sampleNum += 16 - sampleNum%16;
255		}
256		if(sampleNum >= HW::MaxSamples) {
257			sampleNum = HW::MaxSamples;
258		}
259		actualRBW = HW::getADCRate() * window_factors[s.WindowType] / sampleNum;
260		FPGA::SetSamplesPerPoint(sampleNum);
261		// calculate amount of required points
262		points = 2 * (s.f_stop - s.f_start) / actualRBW;
263		// adjust to integer multiple of requested result points (in order to have the same amount of measurements in each bin)
264		points += s.pointNum - points % s.pointNum;
265		binSize = points / s.pointNum;
266		LOG_DEBUG("%u displayed points, resulting in %lu points and bins of size %u", s.pointNum, points, binSize);
267	
268		zerospan = (s.f_start == s.f_stop);
269		// set initial state
270		pointCnt = 0;
271		signalIDstep = 0;
272		trackingFreq = 0;
273		PLLRefIndex = 0;
274		setPLLReference();
275	
276		// enable the required hardware resources
277		Si5351.Enable(SiChannel::Port1LO2);
278		Si5351.Enable(SiChannel::Port2LO2);
279		if (s.trackingGenerator) {
280			Si5351.Enable(SiChannel::LowbandSource);
281		} else {
282			Si5351.Disable(SiChannel::LowbandSource);
283		}
284		FPGA::SetWindow((FPGA::Window) s.WindowType);
285		FPGA::Enable(FPGA::Periphery::LO1Chip);
286		FPGA::Enable(FPGA::Periphery::LO1RF);
287		FPGA::SetupSweep(0, s.trackingGeneratorPort == 1, s.trackingGeneratorPort == 0, s.syncMode != 0, s.syncMaster);
288		FPGA::Enable(FPGA::Periphery::PortSwitch, s.trackingGenerator);
289		FPGA::Enable(FPGA::Periphery::Amplifier, s.trackingGenerator);
290		FPGA::Enable(FPGA::Periphery::Port1Mixer);
291		FPGA::Enable(FPGA::Periphery::Port2Mixer);
292		Trigger::SetMode((Trigger::Mode) s.syncMode);
293	
294		if(s.SignalID) {
295			// use different ADC prescalers depending on RBW: For small RBWs, images with the shifted ADC samplerate can be closer to the IF
296			// because they get suppressed by the RBW filter. For larger RBWs multiple different ADC samplerates are required to move all
297			// aliased images far enough away from the IF. This only works up to about 40kHz RBW. Above that even with signal ID some images
298			// will be present in the processed data
299			if(actualRBW <= 10000) {
300				signalIDsteps = 6;
301				signalIDprescalers = {132, 156};
302			} else {
303				signalIDsteps = 8;
304				signalIDprescalers = {126, 130, 144, 176};
305			}
306		}
307	
308		if (s.UseDFT) {
309			uint32_t spacing = (s.f_stop - s.f_start) / (points - 1);
310			// The DFT can only look at a small bandwidth otherwise the passband of the final ADC filter is visible in the data
311			// Limit to about 30kHz
312			uint32_t maxDFTpoints = 30000 / spacing;
313			// Limit to actual supported number of bins
314			if(maxDFTpoints > FPGA::DFTbins) {
315				maxDFTpoints = FPGA::DFTbins;
316			}
317			DFTpoints = maxDFTpoints;
318			FPGA::DisableInterrupt(FPGA::Interrupt::NewData);
319		} else {
320			DFTpoints = 1; // can only measure one point at a time
321			FPGA::StopDFT();
322			FPGA::EnableInterrupt(FPGA::Interrupt::NewData);
323		}
324	
325		lastLO2 = 0;
326		firstPoint = true;
327		firstSample = true;
328		active = true;
329		StartNextSample();
330	}
331	
332	bool SA::MeasurementDone(const FPGA::SamplingResult &result) {
333		if(!active) {
334			return false;
335		}
336		FPGA::AbortSweep();
337	
338		for(uint16_t i=0;i<DFTpoints;i++) {
339			float port1, port2;
340			if (s.UseDFT) {
341				// use DFT result
342				auto dft = FPGA::ReadDFTResult();
343				port1 = dft.P1;
344				port2 = dft.P2;
345			} else {
346				port1 = fabs(std::complex<float>(result.P1I, result.P1Q));
347				port2 = fabs(std::complex<float>(result.P2I, result.P2Q));
348			}
349			port1 /= sampleNum;
350			port2 /= sampleNum;
351	
352			uint16_t index = i;
353			if (negativeDFT) {
354				// bin order is reversed
355				index = DFTpoints - i - 1;
356			}
357	
358			if(port1 < port1Measurement[index]) {
359				port1Measurement[index] = port1;
360			}
361			if(port2 < port2Measurement[index]) {
362				port2Measurement[index] = port2;
363			}
364		}
365	
366		if (s.UseDFT) {
367			FPGA::StopDFT();
368			// will be started again in StartNextSample
369		}
370	
371		// trigger work function
372		return true;
373	}
374	
375	void SA::Work() {
376		if(!active) {
377			return;
378		}
379	
380		if(!s.SignalID || signalIDstep >= signalIDsteps - 1) {
381			// this measurement point is done, handle result according to detector
382			for(uint16_t i=0;i<DFTpoints;i++) {
383				if(pointCnt + i >= points) {
384					// DFT covered more points than are required for the remaining sweep, can abort here
385					break;
386				}
387				uint16_t binIndex = (pointCnt + i) / binSize;
388				uint32_t pointInBin = (pointCnt + i) % binSize;
389				bool lastPointInBin = pointInBin >= binSize - 1;
390				auto det = (Detector) s.Detector;
391				if(det == Detector::Normal) {
392					det = binIndex & 0x01 ? Detector::PosPeak : Detector::NegPeak;
393				}
394				switch(det) {
395				case Detector::PosPeak:
396					if(pointInBin == 0) {
397						p.spectrumResult.port1 = std::numeric_limits<float>::min();
398						p.spectrumResult.port2 = std::numeric_limits<float>::min();
399					}
400					if(port1Measurement[i] > p.spectrumResult.port1) {
401						p.spectrumResult.port1 = port1Measurement[i];
402					}
403					if(port2Measurement[i] > p.spectrumResult.port2) {
404						p.spectrumResult.port2 = port2Measurement[i];
405					}
406					break;
407				case Detector::NegPeak:
408					if(pointInBin == 0) {
409						p.spectrumResult.port1 = std::numeric_limits<float>::max();
410						p.spectrumResult.port2 = std::numeric_limits<float>::max();
411					}
412					if(port1Measurement[i] < p.spectrumResult.port1) {
413						p.spectrumResult.port1 = port1Measurement[i];
414					}
415					if(port2Measurement[i] < p.spectrumResult.port2) {
416						p.spectrumResult.port2 = port2Measurement[i];
417					}
418					break;
419				case Detector::Sample:
420					if(pointInBin <= binSize / 2) {
421						// still in first half of bin, simply overwrite
422						p.spectrumResult.port1 = port1Measurement[i];
423						p.spectrumResult.port2 = port2Measurement[i];
424					}
425					break;
426				case Detector::Average:
427					if(pointInBin == 0) {
428						p.spectrumResult.port1 = 0;
429						p.spectrumResult.port2 = 0;
430					}
431					p.spectrumResult.port1 += port1Measurement[i];
432					p.spectrumResult.port2 += port2Measurement[i];
433					if(lastPointInBin) {
434						// calculate average
435						p.spectrumResult.port1 /= binSize;
436						p.spectrumResult.port2 /= binSize;
437					}
438					break;
439				case Detector::Normal:
440					// nothing to do, normal detector handled by PosPeak or NegPeak in each sample
441					break;
442				}
443				if(lastPointInBin) {
444					// Send result to application
445					p.type = Protocol::PacketType::SpectrumAnalyzerResult;
446					// measurements are already up to date, fill remaining fields
447					if(zerospan) {
448						uint64_t timestamp = HW::getLastISRTimestamp();
449						if(firstPoint) {
450							p.spectrumResult.us = 0;
451							firstPointTime = timestamp;
452							firstPoint = false;
453						} else {
454							p.spectrumResult.us = timestamp - firstPointTime;
455						}
456					} else {
457						// non-zero span, set frequency
458						p.spectrumResult.frequency = s.f_start + (s.f_stop - s.f_start) * binIndex / (s.pointNum - 1);
459					}
460					// scale approximately (constant determined empirically)
461					p.spectrumResult.port1 /= 253000000.0;
462					p.spectrumResult.port2 /= 253000000.0;
463					if (s.applyReceiverCorrection) {
464						auto correction = Cal::ReceiverCorrection(p.spectrumResult.frequency);
465						p.spectrumResult.port1 *= powf(10.0f, (float) correction.port1 / 100.0f / 20.0f);
466						p.spectrumResult.port2 *= powf(10.0f, (float) correction.port2 / 100.0f / 20.0f);
467					}
468					p.spectrumResult.pointNum = binIndex;
469					Communication::Send(p);
470				}
471			}
472			// setup for next step
473			signalIDstep = 0;
474	
475			if(HW::getStatusUpdateFlag() && pointCnt % 10 == 0) {
476				// send device info every nth point
477				FPGA::Enable(FPGA::Periphery::SourceChip); // needs to enable the chip to get a valid temperature reading
478				Protocol::PacketInfo packet;
479				packet.type = Protocol::PacketType::DeviceStatus;
480				HW::getDeviceStatus(&packet.status, true);
481				FPGA::Disable(FPGA::Periphery::SourceChip);
482				Communication::Send(packet);
483			}
484	
485			if(pointCnt + DFTpoints < points) {
486				pointCnt += DFTpoints;
487			} else {
488				pointCnt = 0;
489				// reset possibly active unlevel flag before next sweep
490				HW::SetOutputUnlevel(false);
491			}
492		} else {
493			// more measurements required for signal ID
494			signalIDstep++;
495		}
496		if(Trigger::GetMode() != Trigger::Mode::ExtRef) {
497			HW::Ref::update();
498		}
499		StartNextSample();
500	}
501	
502	void SA::Stop() {
503		active = false;
504		FPGA::AbortSweep();
505	}
