286	bool FPGA::InitiateSampleRead(ReadCallback cb) {
287		if(busy_reading) {
288			LOG_ERR("ISR while SPI is busy");
289			return false;
290		}
291		callback = cb;
292		static uint8_t cmd[40] = {0xC0, 0x00};
293		// Start data read
294		if(HAL_SPI_GetState(&FPGA_SPI) != HAL_SPI_STATE_READY) {
295			LOG_WARN("SPI abort: %d", HAL_SPI_GetState(&FPGA_SPI));
296			HAL_SPI_Abort(&FPGA_SPI);
297		}
298		Low(CS);
299		busy_reading = true;
300		if(HAL_SPI_TransmitReceive_DMA(&FPGA_SPI, cmd, raw, 40) != HAL_OK) {
301			LOG_ERR("Failed to start SPI DMA");
302			busy_reading = false;
303		}
304		return true;
305	}
306	
307	static int64_t assembleSampleResultValue(uint8_t *raw) {
308	//	LOG_DEBUG("Raw: 0x%02x 0x%02x 0x%02x 0x%02x 0x%02x 0x%02x", raw[4], raw[5], raw[2], raw[3], raw[1], raw[0]);
309		return sign_extend_64(
310				(uint16_t) raw[0] << 8 | raw[1] | (uint32_t) raw[2] << 24
311						| (uint32_t) raw[3] << 16 | (uint64_t) raw[4] << 40
312						| (uint64_t) raw[5] << 32, 48);
313	}
